{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.sku_live_mech_v2 as WITH data AS ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, from_party AS vendor_name, ANY_VALUE( CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+\'))) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END ) AS sku_family, MIN(order_date) AS first_order_date, SUM( CASE WHEN transfer_branch_code != 32 THEN total_qty ELSE NULL END ) AS ordered, SUM( CASE WHEN transfer_branch_code = 8 THEN total_qty ELSE NULL END ) AS south, SUM( CASE WHEN transfer_branch_code = 94 THEN total_qty ELSE NULL END ) AS north FROM SNITCH_DB.MAPLEMONK.LOGIC_PURCHASE_ORDER GROUP BY 1, 2 ), sku_family_count AS ( SELECT sku_family, COUNT(DISTINCT sku_group) AS total_skus FROM data GROUP BY 1 ), north AS ( SELECT sku_no, planned_date, actual_delivered_date, considered_delivered_date, delivery_status_type AS delivery_status_north, erp_po AS po_number_north, NULLIF(TRIM(Breached_Remarks), \'\') AS inward_issue_north FROM ( SELECT sku_no, COALESCE( TRY_TO_DATE(planned_date,\'DD/MM/YYYY\'), TRY_TO_DATE(planned_date,\'DD-MM-YYYY\'), TRY_TO_DATE(planned_date,\'DD-MON-YYYY\'), TRY_TO_DATE(planned_date,\'DD MON YYYY\'), TRY_TO_DATE(planned_date) ) AS planned_date, COALESCE( TRY_TO_DATE(actual_delivered_date,\'DD/MM/YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MM-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MON-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD MON YYYY\'), TRY_TO_DATE(actual_delivered_date) ) AS actual_delivered_date, COALESCE( TRY_TO_DATE(considered_delivered_date,\'DD/MM/YYYY\'), TRY_TO_DATE(considered_delivered_date,\'DD-MM-YYYY\'), TRY_TO_DATE(considered_delivered_date,\'DD-MON-YYYY\'), TRY_TO_DATE(considered_delivered_date,\'DD MON YYYY\'), TRY_TO_DATE(considered_delivered_date) ) AS considered_delivered_date, delivery_status_type, erp_po, Breached_Remarks, \"Invoice no\", CASE WHEN TRIM(UPPER(delivery_status_type)) IN ( \'DELEIVERED_RFID - (OUT_STATION)\', \'DELEIVERED_NON_RFID - (OUT_STATION)\' ) THEN 1 ELSE 0 END AS is_delivered, MAX(CASE WHEN TRIM(UPPER(delivery_status_type)) IN ( \'DELEIVERED_RFID - (OUT_STATION)\', \'DELEIVERED_NON_RFID - (OUT_STATION)\' ) THEN 0 ELSE 1 END) OVER (PARTITION BY sku_no) AS has_undelivered FROM snitch_db.maplemonk.tauru_inward_details_sku_level WHERE sku_no IS NOT NULL ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_no ORDER BY CASE WHEN has_undelivered = 1 THEN (1 - is_delivered) ELSE 0 END DESC, planned_date DESC NULLS LAST, actual_delivered_date DESC NULLS LAST ) = 1 ), south AS ( SELECT sku_no, planned_date, actual_delivered_date, considered_delivered_date, delivery_status_type AS delivery_status_south, erp_po as po_number_south, Breached_Remarks AS inward_issue_south FROM ( SELECT sku_no, COALESCE( TRY_TO_DATE(planned_date,\'DD/MM/YYYY\'), TRY_TO_DATE(planned_date,\'DD-MM-YYYY\'), TRY_TO_DATE(planned_date,\'DD-MON-YYYY\'), TRY_TO_DATE(planned_date,\'DD MON YYYY\'), TRY_TO_DATE(planned_date) ) AS planned_date, COALESCE( TRY_TO_DATE(actual_delivered_date,\'DD/MM/YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MM-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD-MON-YYYY\'), TRY_TO_DATE(actual_delivered_date,\'DD MON YYYY\'), TRY_TO_DATE(actual_delivered_date) ) AS actual_delivered_date, COALESCE( TRY_TO_DATE(TRIM(considered_delivered_date),\'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD/MM/YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MM-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MON-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD MON YY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date),\'DD MON YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date)) ) AS considered_delivered_date, delivery_status_type, erp_po, Breached_Remarks, MAX( CASE WHEN TRIM(delivery_status_type) = \'Not_Yet_Deleivered\' THEN 1 ELSE 0 END ) OVER (PARTITION BY sku_no) AS has_not_delivered FROM snitch_db.maplemonk.SOUTH_INWARD_DETAILS_SKU_LEVEL WHERE sku_no IS NOT NULL ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_no ORDER BY CASE WHEN has_not_delivered = 1 THEN CASE WHEN delivery_status_type = \'Not_Yet_Deleivered\' THEN 0 ELSE 1 END ELSE 0 END, planned_date DESC NULLS LAST, actual_delivered_date DESC NULLS LAST ) = 1 ), puta_qty AS ( SELECT sku_group, SUM(CASE WHEN warehouse_name=\'SAPL-WH2\' THEN qty ELSE 0 END) AS south, SUM(CASE WHEN warehouse_name=\'SAPL-NORTH-TAURU\' THEN qty ELSE 0 END) AS north, SUM(CASE WHEN warehouse_name IN (\'SAPL-WH2\',\'SAPL-NORTH-TAURU\') THEN qty ELSE 0 END) AS inwarded FROM ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+\',1,1), \"Item Type skuCode\"::STRING ))) END AS sku_group, p.\"Warehouse Name\" AS warehouse_name, p.putaway_completed_quantity AS qty FROM snitch_db.maplemonk.putaway_tracking p WHERE p.final_type=\'New Inward\' AND p.\"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-NORTH-TAURU\') ) GROUP BY 1 ), puta_dates AS ( SELECT sku_group, MAX(CASE WHEN warehouse_name=\'SAPL-WH2\' AND is_after_delivery=1 AND rn_best_date=1 THEN putaway_date END) AS inward_date_south, MAX(CASE WHEN warehouse_name=\'SAPL-NORTH-TAURU\' AND is_after_delivery=1 AND rn_best_date=1 THEN putaway_date END) AS inward_date_north FROM ( SELECT t.*, ROW_NUMBER() OVER ( PARTITION BY sku_group, warehouse_name ORDER BY daily_qty DESC, putaway_date DESC ) AS rn_best_date FROM ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+\',1,1), \"Item Type skuCode\"::STRING ))) END AS sku_group, p.\"Warehouse Name\" AS warehouse_name, p.putaway_completed_date::date AS putaway_date, p.putaway_completed_quantity AS qty, s.actual_delivered_date AS south_actual_delivered_date, n.actual_delivered_date AS north_actual_delivered_date, IFF( (p.\"Warehouse Name\"=\'SAPL-WH2\' AND s.actual_delivered_date IS NOT NULL AND p.putaway_completed_date::date >= s.actual_delivered_date) OR (p.\"Warehouse Name\"=\'SAPL-NORTH-TAURU\' AND n.actual_delivered_date IS NOT NULL AND p.putaway_completed_date::date >= n.actual_delivered_date), 1, 0 ) AS is_after_delivery, SUM(p.putaway_completed_quantity) OVER ( PARTITION BY CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+\',1,1), \"Item Type skuCode\"::STRING ))) END, p.\"Warehouse Name\", p.putaway_completed_date::date ) AS daily_qty FROM snitch_db.maplemonk.putaway_tracking p LEFT JOIN south s ON s.sku_no = ( CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+\',1,1), \"Item Type skuCode\"::STRING ))) END ) AND p.\"Warehouse Name\"=\'SAPL-WH2\' LEFT JOIN north n ON n.sku_no = ( CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+\',1,1), \"Item Type skuCode\"::STRING ))) END ) AND p.\"Warehouse Name\"=\'SAPL-NORTH-TAURU\' WHERE p.final_type=\'New Inward\' AND p.\"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-NORTH-TAURU\') ) t WHERE t.is_after_delivery = 1 AND t.daily_qty >= 2 ) GROUP BY 1 ), puta AS ( SELECT q.sku_group, q.south, q.north, q.inwarded, d.inward_date_south, d.inward_date_north, GREATEST(d.inward_date_south, d.inward_date_north) AS inwarded_date FROM puta_qty q LEFT JOIN puta_dates d USING (sku_group) ), final AS ( SELECT d.sku_group AS sku_group, D.sku_family as sku_family, sfc.total_skus AS total_skus, d.ordered, d.vendor_name, d.south South_PO, d.first_order_date, d.north North_PO, p.inwarded, p.south south_inwarded, p.north North_inwarded, p.inward_date_north as inward_date_north, p.inward_date_south as inward_date_south, p.inwarded_date inwarded_date, b.final_live_date, c.allocation_offline, (p.inwarded / NULLIF(d.ordered, 0)) inwarded_prec, ( CASE WHEN d.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN d.north > 0 THEN 1 ELSE 0 END ) AS PO_raised_WH_count, ( CASE WHEN p.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN p.north > 0 THEN 1 ELSE 0 END ) AS inwarded_WH_count, CASE WHEN c.sku_group IS NULL THEN \'No Offline Allocation\' ELSE \'Offline Allocated\' END Offline_Allocated_Status FROM data d LEFT JOIN sku_family_count sfc ON d.sku_family = sfc.sku_family LEFT JOIN puta p USING (sku_group) LEFT JOIN snitch_db.maplemonk.product_journey b USING (sku_group) LEFT JOIN ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' THEN UPPER(TRIM(sku)) ELSE REGEXP_REPLACE(sku, \'-[^-]+$\', \'\') END AS sku_group, MIN(order_date) AS allocation_offline FROM snitch_db.maplemonk.b2b_journey group by 1 ) c ON c.sku_group = d.sku_group WHERE ordered >= 100 ), live_check as ( select distinct sku_group, live_date from snitch_db.maplemonk.category_journey ), base_final AS ( SELECT distinct f.sku_group, F.SKU_FAMILY, f.total_skus, tpi.\"INWARD_remarks \" as inward_remarks, f.ordered, f.vendor_name, cm.collection AS collection, CASE WHEN UPPER(TRIM(REGEXP_REPLACE(f.vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\', \'ADITYA INTERNATIONAL\', \'ANKUSH KNITTING WORKS PRIVATE LIMITED\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'MINERVA FASHION PVT LTD\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'north\' WHEN UPPER(TRIM(REGEXP_REPLACE(f.vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'TEXPORT INDUSTRIES PVT LTD\', \'ANUVARTHH APPARELS PVT.LTD.\', \'BLUE MONKEY CLOTHING COMPANY\', \'G G GARMENTS\', \'K P GARMENT HOUSE\', \'KHARVA APPARELS\', \'LEANDRO FASHION\', \'LOHITH CREATIONS\', \'MARQUEE INDUSTRIES PVT LTD\', \'MAX KNITS INC\', \'MSQ CLOTHING LLP\', \'NALANDA DESIGNERS\', \'OM SHIVA SHAKTHI ENTERPRISES\', \'SAI TEXTILES\', \'SRI SAI TEJA CREATION\', \'V D DECORS\', \'VASUKI CREATIONS\', \'VIGNESH APPEARLS\', \'VIGNESH CREATIONS\', \'VIJAY RAM CREATIONS\', \'AMITHRAJ APPARELS\', \'KNOSKIN FASHIONS PVT. LTD\', \'VR CREATIONS\', \'ABHAY APPARELS\', \'AXCELLER\', \'DIVINITEE GENESIS APPAREL PVT LTD\', \'G T EXPORTS\', \'GO GO INTERNATIONAL PRIVATE LTD\', \'HEVIN CLOTHING\', \'KHATUSHREE INDIA\', \'KP PRODUCTION HOUSE LLP\', \'M SQUARE\', \'PRESTEIGE APPAREL PVT LTD\', \'S R APPARELS\', \'SAI TEXTILES SHADEZ\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'TRIO APPARELS INDIA PVT. LTD\', \'V D FASHIONS\', \'NAVKAR AGENCY\', \'PRANAV INTERNATIONAL KNITWEAR\', \'THANDEESHWARA FASHIONS\', \'ORCHID CLOTH COMPANY\', \'HANUMAN TEXTILES\', \'ADDON CLOTHING\', \'CHECK MATE\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'ETTRO\', \'GROOVY FASHIONS\', \'LAMSOLEE CLOTHING COMPANY\', \'RAUNAK TEXTILES\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISHNU TRADING CO.\', \'VISTA GLOBAL COMPANY\', \'CUT AND SEW EXPORTS\', \'VEEYA FASHION\', \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'A N ASSOCIATES\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'CORE INDIA\', \'GO GO INTERNATIONAL PRIVATE LIMITED\', \'MOTIF CLOTHING CO.\', \'V.D.FASHIONS\', \'WALT ENTERPRISES\', \'VINTAGE\', \'THANDEESWARA FASHIONS\', \'SMART CLOTHING\' ) THEN \'south\' ELSE NULL END AS vendor_region, north.po_number_north AS po_number_north, south.po_number_south AS po_number_south, f.South_PO, f.North_PO, f.inwarded, f.south_inwarded, f.North_inwarded, f.PO_raised_WH_count, f.inwarded_WH_count, f.allocation_offline, f.first_order_date, ROUND(100 * f.inwarded_prec, 1) AS inwarded_prec, CASE WHEN f.PO_raised_WH_count <= f.inwarded_WH_count THEN CASE WHEN f.inward_date_north IS NOT NULL AND f.inward_date_south IS NOT NULL THEN GREATEST(f.inward_date_north, f.inward_date_south) ELSE COALESCE(f.inward_date_north, f.inward_date_south) END END AS WH_Live_date, cj.image_url AS SKU_image, CASE WHEN f.sku_group LIKE \'MP%\' THEN \'Marketplace Specific SKU\' WHEN f.PO_raised_WH_count = 2 and f.inwarded_WH_count =1 and inward_remarks = \'could make live no more inward\' then \'Ready to go live\' WHEN f.PO_raised_WH_count = 2 and f.inwarded_WH_count =1 and inwarded_prec >=0.75 then \'Ready to go live\' WHEN f.PO_Raised_WH_COUNT > 0 and f.PO_raised_WH_count <= f.inwarded_WH_count THEN \'Ready to go live\' ELSE \'Not Ready to go Live\' END AS Remarks, f.Offline_Allocated_Status, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN PO_raised_WH_count = 2 AND inwarded_WH_count = 1 and inward_remarks = \'could make live no more inward\' AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.PO_Raised_WH_COUNT > 0 and f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN PO_raised_WH_count =2 AND inwarded_WH_count =1 and inward_remarks = \'could make live no more inward\' AND f.final_live_date IS not NULL THEN \'Already Live in Online\' WHEN f.PO_Raised_WH_COUNT > 0 and (f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT ) AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN (f.PO_Raised_WH_COUNT > INWARDED_WH_COUNT ) AND f.final_live_date IS NOT NULL THEN \'Should not have made Live\' ELSE \'Do not Make Live\' END END AS Online_Remarks, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.PO_Raised_WH_COUNT > 0 and f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN PO_raised_WH_count = 2 AND inwarded_WH_count = 1 and inward_remarks = \'could make live no more inward\' AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN PO_raised_WH_count =2 AND inwarded_WH_count =1 and inward_remarks = \'could make live no more inward\' AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Offline Allocation Already Done\' WHEN f.PO_Raised_WH_COUNT > 0 and (f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT ) AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Offline Allocation Already Done\' WHEN (f.PO_Raised_WH_COUNT > INWARDED_WH_COUNT ) AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Should not have made Allocations\' ELSE \'Do not Make Allocations\' END END AS Offline_Remarks, lf.live_date, north.planned_date as north_planned_date, north.actual_delivered_date AS north_actual_delivered_date, south.planned_date AS south_planned_date, south.actual_delivered_date AS south_actual_delivered_date, north.considered_delivered_date AS considered_delivered_date_north, south.considered_delivered_date AS considered_delivered_date_south, CASE WHEN f.inward_date_north IS NOT NULL AND north.actual_delivered_date IS NOT NULL AND north.actual_delivered_date > f.inward_date_north THEN north.actual_delivered_date ELSE f.inward_date_north END AS inward_date_north, CASE WHEN f.inward_date_south IS NOT NULL AND south.actual_delivered_date IS NOT NULL AND south.actual_delivered_date > f.inward_date_south THEN south.actual_delivered_date ELSE f.inward_date_south END AS inward_date_south, south.inward_issue_south, north.inward_issue_north, DATEDIFF( \'DAY\', north.planned_date, north.actual_delivered_date ) AS DIFF_NORTH_RECIEVED, DATEDIFF( \'DAY\', south.planned_date, south.actual_delivered_date ) AS DIFF_SOUTH_RECIEVED, north.delivery_status_north AS DELIVERY_STATUS_NORTH, south.delivery_status_south AS DELIVERY_STATUS_SOUTH FROM final f LEFT JOIN snitch_db.maplemonk.\"2PO_1INWARD\" tpi ON UPPER(TRIM(f.sku_group)) = UPPER(TRIM(tpi.\"SKU_GROUP \")) LEFT JOIN north ON f.sku_group = north.sku_no LEFT JOIN south ON f.sku_group = south.sku_no LEFT JOIN snitch_db.maplemonk.category_journey cj ON cj.sku_group = f.sku_group left join live_check lf on f.sku_group = lf.sku_group LEFT JOIN snitch_db.maplemonk.collection_sku_mapped cm ON ( POSITION(\'-\' IN TRIM(cm.sku)) > 0 AND UPPER(TRIM(f.sku_group)) = UPPER(TRIM(cm.sku)) ) OR ( POSITION(\'-\' IN TRIM(cm.sku)) = 0 AND UPPER(TRIM(REGEXP_SUBSTR(f.sku_group::STRING, \'^[^-]+\'))) = UPPER(TRIM(cm.sku)) ) WHERE (lf.live_date > \'2025-11-01\' or lf.live_date is null) and first_order_date >= \'2025-01-01\' AND vendor_name not in (\'TEST SUPPLIER\',\'SNITCH APPAREL PVT LTD.\',\'SNITCH APPAREL PVT. LTD\',\'Vishnu china\',\'Raunak china\',\'SNITCH APPAREL PVT. LTD.\') AND UPPER(TRIM(f.sku_group)) NOT in ( \'PJ07\',\'PJ05\',\'SB4\',\'PP BINS\',\'NSB2\', \'MPB4\',\'MPB7\',\'CBB001\',\'CBS001\', \'89092763660\',\'89092763661\',\'89092763681\',\'4MST2649-02\' ) AND UPPER(TRIM(f.sku_group)) NOT iLIKE \'NT00%\' ), sku_family_inwarded_cte AS ( SELECT sku_family, COUNT(DISTINCT sku_group) AS sku_family_inwarded FROM base_final WHERE online_remarks IN (\'Make it Live in Online\', \'Already Live in Online\') GROUP BY 1 ) SELECT bf.sku_group, bf.sku_family, bf.total_skus, COALESCE(sfi.sku_family_inwarded, 0) AS sku_family_inwarded, CASE WHEN bf.total_skus != 0 AND COALESCE(sfi.sku_family_inwarded, 0) = 0 THEN \'No SKU_GROUP inwarded yet\' WHEN bf.total_skus > COALESCE(sfi.sku_family_inwarded, 0) THEN \'Hold due to color/inward pending\' WHEN bf.total_skus = COALESCE(sfi.sku_family_inwarded, 0) THEN \'Make it live in Online\' END AS sku_family_remarks, bf.inward_remarks, bf.ordered, bf.vendor_name, bf.collection, bf.vendor_region, bf.po_number_north, bf.po_number_south, bf.South_PO, bf.North_PO, bf.inwarded, bf.south_inwarded, bf.North_inwarded, bf.PO_raised_WH_count, bf.inwarded_WH_count, bf.allocation_offline, bf.first_order_date, bf.inwarded_prec, bf.WH_Live_date, bf.SKU_image, bf.Remarks, bf.Offline_Allocated_Status, bf.Online_Remarks, bf.Offline_Remarks, bf.live_date, bf.north_planned_date, bf.north_actual_delivered_date, bf.south_planned_date, bf.south_actual_delivered_date, bf.considered_delivered_date_north, bf.considered_delivered_date_south, bf.inward_date_north, bf.inward_date_south, bf.inward_issue_south, bf.inward_issue_north, bf.DIFF_NORTH_RECIEVED, bf.DIFF_SOUTH_RECIEVED, bf.DELIVERY_STATUS_NORTH, bf.DELIVERY_STATUS_SOUTH FROM base_final bf LEFT JOIN sku_family_inwarded_cte sfi ON bf.sku_family = sfi.sku_family;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            